/**
 * Returns the user's currently-active JMX session, if any.
`isCapturing` is `true` when CDP event capture is armed (the
"recording" phase) and `false` when the session is in the
preview-only browser phase that auto-opens after a JMX project
is created — the browser is live but HTTP events are not being
recorded yet. Both `sessionId` and `isCapturing` are `null` /
`false` when no session exists.

 * @summary Get the active JMX session for the current user
 */
export const GetJmxRecordingStatusResponse = zod
  .object({
    sessionId: zod.string().nullable(),
    isCapturing: zod.boolean(),
  })
  .describe(
    "Snapshot of the calling user's active JMX session. `sessionId`\nis `null` when no session exists. `isCapturing` is `true` only\nonce CDP event capture has been armed (via `start` with\n`capture: true`, or a later `arm` call); preview-only sessions\nreport `false`.\n",
  );

/**
 * Launches a headless Chromium browser instrumented with the
Chrome DevTools Protocol and begins capturing every top-level
HTTP request/response pair the browser makes (XHR, Fetch, and
top-level documents — image/font/stylesheet/media traffic is
filtered out as noise). Returns a `sessionId` the caller passes
back to `POST /jmx/recording/stop`. Captured events are
persisted to a per-session row keyed by that id and consumed
by the downstream JMX XML emitter slice.

 * @summary Start a JMX (JMeter) HTTP capture session
 */
export const startJmxRecordingBodyCaptureDefault = true;

export const StartJmxRecordingBody = zod
  .object({
    projectId: zod.string(),
    jmxFileName: zod.string(),
    startUrl: zod.string().nullish(),
    capture: zod.boolean().default(startJmxRecordingBodyCaptureDefault),
  })
  .describe(
    "Body for `POST \/jmx\/recording\/start`. `projectId` is treated as\nan opaque string identifier (today the URL-encoded `slnPath`\nconvention used elsewhere); `jmxFileName` is the\nproject-relative path of the `.jmx` file being recorded into.\n`startUrl` is optional — when supplied, the recorder navigates\nthe launched browser to it immediately so the caller doesn't\nhave to drive a separate `goto`. `capture` defaults to `true`\n(start CDP event capture immediately); when explicitly `false`\nthe call opens the live-canvas browser in preview-only mode —\nthe user can drive the page but no HTTP events are recorded\nuntil `POST \/jmx\/recording\/arm` is called.\n",
  );

export const StartJmxRecordingResponse = zod.object({
  sessionId: zod.string(),
});

/**
 * Attaches the CDP `Network.*` listeners to an already-open
preview session and flips `isCapturing` to `true`. Used by the
workbench's "Start Recording" button after the auto-opened
preview browser has been driven to the right starting state.
Only the user who owns the session may arm it. If the session
is already capturing, the call is a no-op.

 * @summary Promote a preview JMX session to active capture
 */
export const ArmJmxRecordingBody = zod.object({
  sessionId: zod.string(),
});

export const ArmJmxRecordingResponse = zod.object({
  sessionId: zod.string(),
});

/**
 * Closes the Chromium browser, detaches the CDP session, writes
the captured `JmxHttpEvent[]` to the session's row, and returns
the number of events recorded. Only the user that started the
session may stop it.

 * @summary Stop a JMX HTTP capture session and persist events
 */
export const StopJmxRecordingBody = zod.object({
  sessionId: zod.string(),
});

export const StopJmxRecordingResponse = zod
  .object({
    sessionId: zod.string(),
    eventCount: zod.number(),
    jmxFilePath: zod.string().nullable(),
    warnings: zod.array(zod.string()),
  })
  .describe(
    "Result of `POST \/jmx\/recording\/stop`. `jmxFilePath` is the\nproject-root-relative path of the emitted `.jmx` plan (e.g.\n`jmx\/login-flow.jmx`), or `null` when emission was skipped —\nfor example, when no HTTP events were captured or when the\nproject marker was missing. `warnings` carries non-fatal\nmessages from the emitter \/ validator (credential leak refusal,\nmissing marker, etc.) so the workbench can surface them.\n",
  );

